import { useEffect, useRef, useState } from "react";
import { useParams } from "react-router-dom";
import api from "../api/axios";
import { useSocket } from "../context/SocketContext";
import { useAuth } from "../context/AuthContext";
import StatusTrack from "../components/StatusTrack";
import LiveMap from "../components/LiveMap";

export default function OrderTracking() {
  const { id } = useParams();
  const { socket } = useSocket();
  const { user } = useAuth();
  const [order, setOrder] = useState(null);
  const [agentPos, setAgentPos] = useState(null);
  const watchId = useRef(null);

  useEffect(() => {
    api.get(`/orders/${id}`).then(({ data }) => {
      setOrder(data);
      if (data.agentLocation?.lat) setAgentPos(data.agentLocation);
    });
  }, [id]);

  useEffect(() => {
    if (!socket) return;
    socket.emit("order:watch", id);

    const onStatus = ({ orderId, status }) => {
      if (orderId !== id) return;
      setOrder((prev) => (prev ? { ...prev, status } : prev));
    };
    const onLocation = ({ orderId, lat, lng }) => {
      if (orderId !== id) return;
      setAgentPos({ lat, lng });
    };
    const onAgentAssigned = ({ orderId, agentName }) => {
      if (orderId !== id) return;
      setOrder((prev) => (prev ? { ...prev, agent: { name: agentName } } : prev));
    };

    socket.on("order:status", onStatus);
    socket.on("order:agent_location", onLocation);
    socket.on("order:agent_assigned", onAgentAssigned);

    return () => {
      socket.emit("order:unwatch", id);
      socket.off("order:status", onStatus);
      socket.off("order:agent_location", onLocation);
      socket.off("order:agent_assigned", onAgentAssigned);
    };
  }, [socket, id]);

  // If the person viewing this page IS the assigned delivery agent, stream
  // their real GPS position so the customer's map updates live.
  useEffect(() => {
    if (!socket || !order || user?.role !== "agent") return;
    if (String(order.agent?._id || order.agent) !== String(user._id) && order.agent?.name === undefined) {
      // not assigned yet or not this agent — still fine to skip
    }
    if (!navigator.geolocation) return;

    watchId.current = navigator.geolocation.watchPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords;
        socket.emit("agent:location", { orderId: id, lat: latitude, lng: longitude });
        setAgentPos({ lat: latitude, lng: longitude });
      },
      () => {},
      { enableHighAccuracy: true, maximumAge: 5000 }
    );

    return () => {
      if (watchId.current) navigator.geolocation.clearWatch(watchId.current);
    };
  }, [socket, order, user, id]);

  if (!order) return <div className="page">Loading order…</div>;

  return (
    <div className="page">
      <div className="eyebrow">Order #{order._id.slice(-6).toUpperCase()}</div>
      <h1>
        {order.status === "delivered" ? "Delivered" : "Tracking your order"}
      </h1>
      <hr className="route-rule" style={{ margin: "20px 0 8px" }} />

      <StatusTrack status={order.status} />

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 24, marginTop: 20 }}>
        <div>
          <LiveMap lat={agentPos?.lat} lng={agentPos?.lng} label={order.agent?.name || "Delivery agent"} />
        </div>
        <div className="card">
          <h3>Order summary</h3>
          <hr className="route-rule" style={{ margin: "12px 0" }} />
          {order.items.map((item, i) => (
            <div key={i} style={{ display: "flex", justifyContent: "space-between", fontSize: 14, marginBottom: 6 }}>
              <span>{item.quantity}× {item.name}</span>
              <span style={{ fontFamily: "var(--font-mono)" }}>₹{item.price * item.quantity}</span>
            </div>
          ))}
          <hr className="route-rule" style={{ margin: "12px 0" }} />
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "var(--font-mono)" }}>
            <span>Total</span>
            <span>₹{order.totalAmount}</span>
          </div>
          {order.agent?.name && (
            <p style={{ marginTop: 16, fontSize: 14, color: "var(--paper-dim)" }}>
              Delivery agent: <strong style={{ color: "var(--paper)" }}>{order.agent.name}</strong>
            </p>
          )}
        </div>
      </div>
    </div>
  );
}
